import { mkdir, readFile, writeFile } from "node:fs/promises"
import { dirname } from "node:path"
import type { ArticleBlock, ArticleImage, ArticleInline, ArticleRecord, RelatedArticle } from "../../components/blog/article-types.ts"

export function renderGeneratedArticles(articles: ArticleRecord[]) {
  return `import type { ArticleRecord } from "@/components/blog/article-types"

// Generated by scripts/import-eduvert-blogs.ts. Do not edit by hand.

export const generatedArticles = ${JSON.stringify(articles, null, 2)} satisfies ArticleRecord[]
`
}

export function renderGeneratedJournal(articles: ArticleRecord[]) {
  const journal: RelatedArticle[] = articles.map((article) => ({
    slug: article.slug,
    title: article.title,
    category: article.category,
    publishedOn: article.publishedOn,
    summary: article.summary,
    mark: article.mark,
  }))
  return `import type { RelatedArticle } from "@/components/blog/article-types"

// Generated by scripts/import-eduvert-blogs.ts. Do not edit by hand.

export const generatedJournalArticles: RelatedArticle[] = ${JSON.stringify(journal, null, 2)}
`
}

export async function writeGeneratedModules(articlesPath: string, journalPath: string, articles: ArticleRecord[]) {
  for (const article of articles) assertArticle(article)
  await mkdir(dirname(articlesPath), { recursive: true })
  await writeFile(articlesPath, renderGeneratedArticles(articles))
  await writeFile(journalPath, renderGeneratedJournal(articles))
}

export async function appendGeneratedArticles(path: string, articles: ArticleRecord[]) {
  if (articles.length === 0) return
  for (const article of articles) assertArticle(article)
  const source = await readFile(path, "utf8")
  await writeFile(path, appendArrayLiteral(source, "] satisfies ArticleRecord[]", articles))
}

export async function appendGeneratedJournal(path: string, articles: ArticleRecord[]) {
  if (articles.length === 0) return
  const cards: RelatedArticle[] = articles.map((article) => ({
    slug: article.slug,
    title: article.title,
    category: article.category,
    publishedOn: article.publishedOn,
    summary: article.summary,
    mark: article.mark,
    ...(article.featuredImage === null ? { featuredImage: null } : {}),
  }))
  const source = await readFile(path, "utf8")
  const closing = source.trimEnd().endsWith("]") ? "]" : ""
  if (!closing) throw new Error(`Could not append journal cards in ${path}`)
  await writeFile(path, appendArrayLiteral(source, "]", cards))
}

export async function appendMetadata(path: string, entries: unknown[]) {
  if (entries.length === 0) return
  const source = await readFile(path, "utf8")
  await writeFile(path, appendArrayLiteral(source, "]", entries))
}

export async function writeMetadata(path: string, metadata: unknown) {
  await mkdir(dirname(path), { recursive: true })
  await writeFile(path, `${JSON.stringify(metadata, null, 2)}\n`)
}

function appendArrayLiteral(source: string, closing: string, entries: unknown[]) {
  const index = source.lastIndexOf(closing)
  if (index < 0) throw new Error(`Could not find ${closing}`)
  const body = entries.map((entry) => JSON.stringify(entry, null, 2).split("\n").map((line) => `  ${line}`).join("\n")).join(",\n")
  return `${source.slice(0, index).trimEnd()},\n${body}\n${source.slice(index)}`
}

function assertArticle(article: ArticleRecord) {
  if (!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(article.slug)) throw new Error(`Invalid slug ${article.slug}`)
  if (!article.title.trim()) throw new Error(`Missing title for ${article.slug}`)
  if (!categories.has(article.category)) throw new Error(`Invalid category for ${article.slug}`)
  if (!/^\d{4}-\d{2}-\d{2}$/.test(article.publishedOn)) throw new Error(`Invalid date for ${article.slug}`)
  if (!article.summary.trim()) throw new Error(`Missing summary for ${article.slug}`)
  if (!marks.has(article.mark)) throw new Error(`Invalid mark for ${article.slug}`)
  if (article.blocks.length === 0) throw new Error(`Missing body for ${article.slug}`)
  if (article.featuredImage) assertImage(article.featuredImage, article.slug)
  if (article.hero) assertImage(article.hero, article.slug)
  for (const block of article.blocks) assertBlock(block, article.slug)
}

function assertImage(image: ArticleImage, slug: string) {
  if (!image.src.startsWith("/images/blog/")) throw new Error(`Image for ${slug} is not a local blog asset`)
  if (!image.width || !image.height) throw new Error(`Image for ${slug} is missing dimensions`)
}

function assertBlock(block: ArticleBlock, slug: string) {
  switch (block.type) {
    case "paragraph":
      if (block.inlines.length === 0) throw new Error(`Empty paragraph in ${slug}`)
      for (const inline of block.inlines) assertInline(inline, slug)
      return
    case "heading":
      if ((block.level !== 2 && block.level !== 3) || !block.id || !block.text.trim()) throw new Error(`Invalid heading in ${slug}`)
      return
    case "list":
      if (block.items.length === 0) throw new Error(`Empty list in ${slug}`)
      return
    case "table":
      if (block.rows.length === 0) throw new Error(`Empty table in ${slug}`)
      return
    default: {
      const unhandled: never = block
      throw new Error(`Unhandled block in ${slug}: ${JSON.stringify(unhandled)}`)
    }
  }
}

function assertInline(inline: ArticleInline, slug: string) {
  switch (inline.type) {
    case "text":
    case "strong":
    case "emphasis":
      if (!inline.text) throw new Error(`Empty inline in ${slug}`)
      return
    case "link":
      if (!inline.text || !inline.href) throw new Error(`Invalid link in ${slug}`)
      return
    default: {
      const unhandled: never = inline
      throw new Error(`Unhandled inline in ${slug}: ${JSON.stringify(unhandled)}`)
    }
  }
}

const categories = new Set(["SEO & Search", "AI & Marketing", "Paid Advertising", "Social Media Marketing", "Analytics", "Digital Marketing", "Career & Skills"])

const marks = new Set(["letters", "work", "tasks", "pair", "search", "quote", "calendar", "authority"])
